(()=>{'use strict';const $=s=>document.querySelector(s),mq=matchMedia('(prefers-reduced-motion: reduce)'),preferenceKey='dotlab-motion-enabled';let progress=0,mode='tangent',manual=true,playing=false,frame=null,startTime=0,startProgress=0;try{manual=localStorage.getItem(preferenceKey)!=='false'}catch{}function allowed(){return manual&&!mq.matches&&!document.hidden}function status(text){$('#status').textContent=text}function controls(){const focused=document.activeElement;$('#play').textContent=playing?'一時停止 Ⅱ':progress>=1?'もう一度再生 ▶':progress>0?'続きから再生 ▶':'一度だけ再生 ▶';$('#play').disabled=!allowed();$('#replay').disabled=!allowed();$('#motion').setAttribute('aria-pressed',String(manual&&!mq.matches));$('#motion').textContent=mq.matches?'動き OFF · 端末設定':'動き '+(manual?'ON':'OFF');$('#motion').disabled=mq.matches;if((focused===$('#motion')&&mq.matches)||((focused===$('#play')||focused===$('#replay'))&&!allowed()))$('#progress').focus({preventScroll:true})}function cancel(){if(frame!==null)cancelAnimationFrame(frame);frame=null;playing=false;controls()}function render(){const p=HeadingModel.pose(progress,mode);$('#glyph').setAttribute('transform','translate('+p.x+' '+p.y+') rotate('+p.angle+')');$('#progress').value=String(Math.round(progress*1000));$('#clock').textContent=(progress*2.8).toFixed(2)+' / 2.80 s';$('#distance').textContent='距離 '+(progress*100).toFixed(1)+' %';$('#heading').textContent='向き '+p.angle.toFixed(1)+'°';$('#center').textContent='基準点 '+p.x.toFixed(1)+', '+p.y.toFixed(1);$('#progress').setAttribute('aria-valuetext','道の距離 '+(progress*100).toFixed(1)+'%、'+(mode==='tangent'?'進路に向く':'水平のまま'));$('#art-description').textContent='道の距離'+(progress*100).toFixed(1)+'%の地点。黄色い端が前です。'+(mode==='tangent'?'接線に沿った向き。':'水平に固定した向き。')}function tick(now){frame=null;if(!playing||!allowed()){cancel();return}progress=Math.min(1,Math.max(progress,startProgress+Math.max(0,now-startTime)/HeadingModel.DURATION));render();if(progress>=1){cancel();status('終点で停止しました。繰り返しはありません。')}else frame=requestAnimationFrame(tick)}function play(restart){cancel();if(!allowed())return;if(restart||progress>=1)progress=0;startProgress=progress;startTime=performance.now();playing=true;render();controls();status('一度だけ再生中。向きを切り替えると同じ地点で止まります。');frame=requestAnimationFrame(tick)}$('#play').addEventListener('click',()=>{if(playing){cancel();status('一時停止。同じ基準点位置で向きを比較できます。')}else play(false)});$('#replay').addEventListener('click',()=>play(true));$('#reset').addEventListener('click',()=>{cancel();progress=0;render();controls();status('開始点で停止。自動では再生しません。')});$('#progress').addEventListener('input',e=>{cancel();progress=Number(e.target.value)/1000;render();controls();status('選んだ地点で静止しています。')});document.querySelectorAll('input[name="orientation"]').forEach(input=>input.addEventListener('change',()=>{cancel();mode=input.value;$('#mode-label').textContent=mode==='tangent'?'TANGENT HEADING':'FIXED HORIZONTAL';render();status('基準点の位置を変えずに、向きを切り替えました。')}));$('#motion').addEventListener('click',()=>{manual=!manual;try{localStorage.setItem(preferenceKey,String(manual))}catch{}cancel();status(manual?'動きON。操作するまで再生しません。':'動きOFF。スライダーと向きの比較は使えます。')});mq.addEventListener('change',()=>{cancel();status(mq.matches?'端末設定で動きOFF。静止比較は使えます。':'端末設定を反映しました。自動では再生しません。')});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancel();status('画面を離れたため一時停止しました。')}controls()});addEventListener('pagehide',cancel);addEventListener('storage',e=>{if(e.key===preferenceKey){manual=e.newValue!=='false';cancel();status('動きの設定を反映しました。自動では再生しません。')}});addEventListener('pageshow',()=>{try{manual=localStorage.getItem(preferenceKey)!=='false'}catch{}cancel();status(allowed()?'再生するか、スライダーと向きで静止比較できます。':'動きOFF。スライダーと向きの比較は使えます。')});document.documentElement.classList.add('enhanced');render();controls();})();
